$ErrorActionPreference='Stop';$folder=[IO.Path]::GetFullPath('orchestration/validation');$out=Join-Path $folder 'word-native-heading-fixture.docx';$pdf=Join-Path $folder 'word-native-heading-fixture.pdf';$started=Get-Date;$prior=@(Get-CimInstance Win32_Process -Filter "Name='WINWORD.EXE'"|%{[int]$_.ProcessId});$word=$null;$doc=$null;$owned=$false;$pidOwned=$null;$report=[ordered]@{prior=$prior;started=$started.ToString('o');closed=$false}
function Find-Owned($pids,$t){$a=@(Get-CimInstance Win32_Process -Filter "Name='WINWORD.EXE'"|?{[int]$_.ProcessId -notin $pids -and $_.CreationDate -and ([datetime]$_.CreationDate) -ge $t.AddSeconds(-2)});if($a.Count-ne 1){return $null};$p=$a[0];if($p.ExecutablePath-ne'C:\Program Files\Microsoft Office\Root\Office16\WINWORD.EXE'-or$p.CommandLine-notmatch'/Automation\s+-Embedding'){return $null};$p}
try{$word=New-Object -ComObject Word.Application;$lim=(Get-Date).AddSeconds(20);do{Start-Sleep -Milliseconds 250;$proof=Find-Owned $prior $started}while($null-eq$proof-and(Get-Date)-lt$lim);if($null-eq$proof){throw'Word ownership proof missing'};$owned=$true;$pidOwned=[int]$proof.ProcessId;$report.process=[ordered]@{pid=$proof.ProcessId;parent=$proof.ParentProcessId;created=$proof.CreationDate;path=$proof.ExecutablePath;command=$proof.CommandLine;session=$proof.SessionId};if([int]$word.Documents.Count-ne 0){throw'New Word has documents'};$word.Visible=$false;$word.DisplayAlerts=0;$doc=$word.Documents.Add();$sel=$word.Selection
$sel.Style=-2;$sel.TypeText('Original heading title');$sel.TypeParagraph();$first=$doc.Paragraphs.Item(1).Range.Duplicate;$doc.Bookmarks.Add('SourceHeading',$first)|Out-Null
$sel.Style=-2;$sel.TypeText('Second heading');$sel.TypeParagraph();$sel.InsertBreak(7);$sel.Style=-2;$sel.TypeText('Page two heading');$sel.TypeParagraph()
# Put the fixture TOC after the source headings so its insertion boundary cannot capture the source bookmark.
$r=$doc.Range($doc.Content.End-1,$doc.Content.End-1);$toc=$doc.TablesOfContents.Add($r,$true,1,3,$false,'',$true,$true,'',$true,$false,$true);$toc.Update();$report.before=$toc.Range.Text;$report.tocCountBefore=$doc.TablesOfContents.Count;$source=$doc.Bookmarks.Item('SourceHeading').Range.Duplicate;$report.sourceBookmarkText=$source.Text;$report.sourceStart=$source.Start;$report.sourceEnd=$source.End;$report.tocStart=$toc.Range.Start;$report.tocEnd=$toc.Range.End;if($source.Start -lt $toc.Range.End -and $source.End -gt $toc.Range.Start){throw 'Source bookmark overlaps TOC result'};if(-not $source.Text.Contains('Original heading title')){throw 'Bookmark does not point at source heading'}
$source.Text='Changed heading title';$doc.Bookmarks.Add('SourceHeading',$source)|Out-Null;$report.renameText=($doc.Bookmarks.Item('SourceHeading').Range.Text -match 'Changed heading title');$doc.Repaginate();$report.tocCountAfterPagination=$doc.TablesOfContents.Count;$doc.TablesOfContents.Item(1).Update();$report.after=$doc.TablesOfContents.Item(1).Range.Text;$report.containsChanged=$report.after.Contains('Changed heading title');$report.containsPageTwo=$report.after.Contains('Page two heading');$report.fields=@($doc.Fields|%{[ordered]@{code=$_.Code.Text;result=$_.Result.Text}});$doc.SaveAs2($out,16);$doc.ExportAsFixedFormat($pdf,17);$report.documentText=$doc.Content.Text
}catch{$report.error=$_.ToString();$report.stack=$_.ScriptStackTrace;Write-Output ('ERROR '+$_.ToString())}finally{$noSave=0;if($doc){$doc.Close([ref]$noSave);[void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($doc)};if($word){if($owned){$word.Quit([ref]$noSave)};[void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($word)};[GC]::Collect();[GC]::WaitForPendingFinalizers();if($pidOwned){$d=(Get-Date).AddSeconds(20);do{Start-Sleep -Milliseconds 500;$alive=Get-CimInstance Win32_Process -Filter "ProcessId=$pidOwned" -EA SilentlyContinue}while($null-ne$alive-and(Get-Date)-lt$d);$report.closed=$null-eq$alive};$report|ConvertTo-Json -Depth 8|Set-Content -LiteralPath (Join-Path $folder 'word-native-heading-fixture-report.json') -Encoding utf8}
